<?php foreach($data['exceptions'] as $exception): ?><tr data-owner="<?=$escape($cs_owner($exception))?>"><td><?=$escape($cs_label($exception))?><div class="path"><?=$escape($exception['path']?:'Whole website')?></div></td><td><?=$escape($exception['kind'])?></td><td class="path"><?=$escape($exception['sha256']??$exception['signature'])?></td><td><?=$exception['enabled']?'Enabled':'Disabled'?></td><td><?php if($exception['enabled']): ?><button class="button" data-action="exception-remove" data-exception_id="<?=$escape($exception['id'])?>">Remove exception</button><?php endif ?></td></tr><?php endforeach ?>
